import{_ as t,o as e,c as a,ae as n}from"./chunks/framework.Dzr56EFm.js";const c=JSON.parse('{"title":"设计趋势 - 2026-06-12","description":"","frontmatter":{"date":"2026-06-12T00:00:00.000Z","category":"UX Trend"},"headers":[],"relativePath":"daily/2026-06-12-uxtrend.md","filePath":"daily/2026-06-12-uxtrend.md"}'),o={name:"daily/2026-06-12-uxtrend.md"};function s(i,r,g,p,h,l){return e(),a("div",null,[...r[0]||(r[0]=[n('<h1 id="设计趋势-2026-06-12" tabindex="-1">设计趋势 - 2026-06-12 <a class="header-anchor" href="#设计趋势-2026-06-12" aria-label="Permalink to &quot;设计趋势 - 2026-06-12&quot;">​</a></h1><blockquote><p>AI交互方式、Prompt UX、Agent UX、Workflow</p></blockquote><h2 id="今日概览" tabindex="-1">今日概览 <a class="header-anchor" href="#今日概览" aria-label="Permalink to &quot;今日概览&quot;">​</a></h2><p>今日设计趋势资讯聚焦于AI在设计领域的应用。AI代理工作流设计模式被深入探讨，AI技术正逐步融入设计流程，提升创意工作的适应性和团队协作。同时，AI交互模式的探索旨在建立人与AI的信任关系。最值得关注的是AI在设计中的应用，它正改变我们的创造方式，以及构建信任与增强互动的AI UX模式的实际应用，这两者对未来设计领域的创新至关重要。</p><hr><h3 id="_1-ai代理工作流设计模式概览" tabindex="-1">1. AI代理工作流设计模式概览 <a class="header-anchor" href="#_1-ai代理工作流设计模式概览" aria-label="Permalink to &quot;1. AI代理工作流设计模式概览&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/binome/ai-agent-workflow-design-patterns-an-overview-cf9e1f609696" target="_blank" rel="noreferrer">AI Agent Workflow Design Patterns — An Overview</a></p><p><strong>一句话摘要</strong>: 探讨AI代理工作流设计模式，分类并举例说明。</p><p><strong>能解决什么问题</strong>: 如何设计AI代理以模拟人类推理和执行任务。</p><p><strong>产品应用</strong>: 可应用于开发智能代理，通过工作流模式灵活处理问题。</p><p><strong>示例场景</strong>: 智能助手使用ReAct模式整合工具解决问题。</p><hr><h3 id="_2-ai在设计中的应用-改变我们的创造方式" tabindex="-1">2. AI在设计中的应用：改变我们的创造方式 <a class="header-anchor" href="#_2-ai在设计中的应用-改变我们的创造方式" aria-label="Permalink to &quot;2. AI在设计中的应用：改变我们的创造方式&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://www.figma.com/resource-library/ai-in-design" target="_blank" rel="noreferrer">AI in Design: Transforming the Way We Create | Figma</a></p><p><strong>一句话摘要</strong>: AI技术将深度整合进设计工作流程，提升创意工作的适应性和团队协作。</p><p><strong>能解决什么问题</strong>: 解决设计过程中的自动化和个性化需求，提高效率和用户体验。</p><p><strong>产品应用</strong>: 可以应用到产品设计中，通过AI辅助生成设计选项，优化团队协作。</p><p><strong>示例场景</strong>: 设计师利用AI生成多种界面布局，根据用户行为进行个性化调整。</p><hr><h3 id="_3-ai交互模式-让用户识别和与ai驱动功能互动" tabindex="-1">3. AI交互模式：让用户识别和与AI驱动功能互动 <a class="header-anchor" href="#_3-ai交互模式-让用户识别和与ai驱动功能互动" aria-label="Permalink to &quot;3. AI交互模式：让用户识别和与AI驱动功能互动&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/@flik185/ai-interaction-patterns-giving-users-ways-to-recognize-and-interact-with-ai-driven-features-22055a91206b" target="_blank" rel="noreferrer">AI Interaction Patterns: Giving Users Ways to Recognize and Interact With Ai-Driven Features</a></p><p><strong>一句话摘要</strong>: 通过交互模式建立人与AI的信任关系</p><p><strong>能解决什么问题</strong>: 如何让用户识别并有效互动AI功能</p><p><strong>产品应用</strong>: 可应用于AI工具，如聊天机器人、分析仪表板等</p><p><strong>示例场景</strong>: 聊天机器人中明确AI身份，提供操作指引</p><hr><h3 id="_4-为代理型用户体验设计指南" tabindex="-1">4. 为代理型用户体验设计指南 <a class="header-anchor" href="#_4-为代理型用户体验设计指南" aria-label="Permalink to &quot;4. 为代理型用户体验设计指南&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/ai-ux-designers/era-of-agentive-ux-not-agentic-64dd765a0372" target="_blank" rel="noreferrer">Designing for Agentive UX — A Guide</a></p><p><strong>一句话摘要</strong>: 设计代理型用户体验，通过持续循环预测用户未来需求。</p><p><strong>能解决什么问题</strong>: 解决用户未知未来需求的发现和满足问题。</p><p><strong>产品应用</strong>: 可应用于个性化推荐系统，通过算法预测用户偏好。</p><p><strong>示例场景</strong>: 智能助手根据用户习惯自动推荐新闻或音乐。</p><hr><h3 id="_5-构建信任与增强互动-7个关键ai-ux模式的实际应用" tabindex="-1">5. 构建信任与增强互动：7个关键AI UX模式的实际应用 <a class="header-anchor" href="#_5-构建信任与增强互动-7个关键ai-ux模式的实际应用" aria-label="Permalink to &quot;5. 构建信任与增强互动：7个关键AI UX模式的实际应用&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/bestfolios/building-trust-and-enhancing-interactions-7-essential-ai-ux-patterns-in-action-12e7604de435" target="_blank" rel="noreferrer">Building Trust and Enhancing Interactions: 7 Essential AI UX Patterns in Action</a></p><p><strong>一句话摘要</strong>: 文章介绍了7种AI UX模式，提升用户互动和信任。</p><p><strong>能解决什么问题</strong>: 解决AI交互中的信任和效率问题，提升用户体验。</p><p><strong>产品应用</strong>: 可以应用到实际产品中，如代码助手和图像处理工具。</p><p><strong>示例场景</strong>: ChatGPT的智能代码块和Topaz Gigapixel的图像放大。</p><hr><h3 id="_6-2026年顶级网页设计趋势-figma" tabindex="-1">6. 2026年顶级网页设计趋势 - Figma <a class="header-anchor" href="#_6-2026年顶级网页设计趋势-figma" aria-label="Permalink to &quot;6. 2026年顶级网页设计趋势 - Figma&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://www.figma.com/resource-library/web-design-trends" target="_blank" rel="noreferrer">Top Web Design Trends for 2026 - Figma</a></p><p><strong>一句话摘要</strong>: AI技术推动网页设计更智能、个性化。</p><p><strong>能解决什么问题</strong>: 提高网站交互性、可访问性和个性化体验。</p><p><strong>产品应用</strong>: 可以通过Figma Make等工具实现智能布局、交互代理和AI驱动体验。</p><p><strong>示例场景</strong>: 使用AI聊天机器人提升用户咨询效率。</p><hr><h3 id="_7-ai驱动产品工作流程的设计思维-为genai创新带来结构" tabindex="-1">7. AI驱动产品工作流程的设计思维：为GenAI创新带来结构 <a class="header-anchor" href="#_7-ai驱动产品工作流程的设计思维-为genai创新带来结构" aria-label="Permalink to &quot;7. AI驱动产品工作流程的设计思维：为GenAI创新带来结构&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/@1993Tikku/design-thinking-for-ai-driven-product-workflows-bringing-structure-to-genai-innovations-07812c814496" target="_blank" rel="noreferrer">Design Thinking for AI-Driven Product Workflows: Bringing Structure to GenAI Innovations</a></p><p><strong>一句话摘要</strong>: 以用户为中心的设计思维是AI产品成功的关键。</p><p><strong>能解决什么问题</strong>: 如何在AI热潮中创造符合市场需求的持久解决方案。</p><p><strong>产品应用</strong>: 适用于产品开发，通过设计思维确保AI产品满足用户需求。</p><p><strong>示例场景</strong>: 企业利用设计思维开发更懂用户需求的AI助手。</p><hr><h3 id="_8-如何使用chatgpt新图像生成器创建ui" tabindex="-1">8. 如何使用ChatGPT新图像生成器创建UI <a class="header-anchor" href="#_8-如何使用chatgpt新图像生成器创建ui" aria-label="Permalink to &quot;8. 如何使用ChatGPT新图像生成器创建UI&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/design-bootcamp/how-i-created-ui-with-chatgpts-new-image-generator-4o-d52389a5833e" target="_blank" rel="noreferrer">How I created UI with ChatGPT’s new image generator (4o)</a></p><p><strong>一句话摘要</strong>: ChatGPT新图像生成器大幅提升UI视觉原型生成的精确度。</p><p><strong>能解决什么问题</strong>: 解决UI设计中视觉原型快速生成和精确调整的需求。</p><p><strong>产品应用</strong>: 可应用于产品原型设计，通过对话生成不同布局和风格的UI视觉原型。</p><p><strong>示例场景</strong>: 设计一个具有品牌特色的大胆且吸引人的用户界面。</p><hr><h3 id="_9-ai-ux-人工智能代理的体验设计" tabindex="-1">9. AI/UX：人工智能代理的体验设计 <a class="header-anchor" href="#_9-ai-ux-人工智能代理的体验设计" aria-label="Permalink to &quot;9. AI/UX：人工智能代理的体验设计&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/i-ux/ai-ux-experience-design-of-ai-agents-12e1051fa065" target="_blank" rel="noreferrer">AI/UX: Experience Design of AI Agents</a></p><p><strong>一句话摘要</strong>: AI代理将参与服务生态系统，执行任务并代表用户做决策。</p><p><strong>能解决什么问题</strong>: 解决传统以人为中心的UX设计无法满足AI代理需求的问题。</p><p><strong>产品应用</strong>: 可以应用到需要自动化服务和决策支持的实际产品中。</p><p><strong>示例场景</strong>: AI代理代表用户与航空公司协商旅行安排。</p><hr><h3 id="_10-设计师的提示工程实用指南-我学到的" tabindex="-1">10. 设计师的提示工程实用指南：我学到的 <a class="header-anchor" href="#_10-设计师的提示工程实用指南-我学到的" aria-label="Permalink to &quot;10. 设计师的提示工程实用指南：我学到的&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/@uxraspberry/prompt-engineering-for-designers-a-practical-guide-what-i-learned-so-far-140d70879c7e" target="_blank" rel="noreferrer">Prompt engineering for designers: a practical guide (what I learned so far)</a></p><p><strong>一句话摘要</strong>: 掌握不同AI工具的提示工程技巧，提升设计效率。</p><p><strong>能解决什么问题</strong>: 如何根据不同AI工具特性优化设计工作流程。</p><p><strong>产品应用</strong>: 适用于实际产品设计，通过精确提示提升AI工具辅助效果。</p><p><strong>示例场景</strong>: 使用ChatGPT优化自由职业者应用的注册流程。</p><hr>',75)])])}const u=t(o,[["render",s]]);export{c as __pageData,u as default};
